/**
 * Canonical copy registry for the Service Writer lifecycle.
 *
 * This registry is intentionally provider-neutral: delivery adapters receive a
 * rendered subject/body, while event producers depend only on a stable key.
 */

export type LifecyclePurpose =
  | "transactional"
  | "service_reminder"
  | "appointment_update"
  | "payment_request"
  | "authentication"
  | "marketing";

export type LifecycleTemplate = {
  key: string;
  category: string;
  title: string;
  subject: string;
  preview: string;
  headline: string;
  body: string;
  ctaLabel: string;
  essentialInformation: string;
  purpose: LifecyclePurpose;
};

export type LifecycleVariables = Record<string, string | number | boolean | null | undefined>;

const VARIABLE_PATTERN = /\{\{\s*([a-zA-Z0-9_.-]+)\s*\}\}/g;

function valueFor(variables: LifecycleVariables, path: string): string {
  const value = variables[path];
  return value === null || value === undefined || value === "" ? `{{${path}}}` : String(value);
}

function requiredVariables(template: LifecycleTemplate): string[] {
  const source = [template.subject, template.preview, template.headline, template.body, template.essentialInformation].join("\n");
  return [...new Set([...source.matchAll(VARIABLE_PATTERN)].map((match) => match[1]))];
}

function escapeHtml(value: string): string {
  return value.replace(/[&<>"']/g, (character) => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#39;",
  })[character] ?? character);
}

export function interpolate(value: string, variables: LifecycleVariables): string {
  return value.replace(VARIABLE_PATTERN, (_match, path: string) => valueFor(variables, path));
}

