  "appointment_booking_sequence.new_appointment_booked": { key: "appointment_booking_sequence.new_appointment_booked", category: "3. Appointment booking sequence", title: "New appointment booked", subject: "New appointment booked", preview: "A new appointment has been created and is ready for your team to review.", headline: "New appointment booked", body: "Hello,\n\nThis message concerns your appointment and the service visit it represents. A new appointment has been created and is ready for your team to review.\n\nHere is the information currently associated with this update: Customer: {{customer.full_name}} | Service: {{appointment.service}} | Date: {{appointment.date}} at {{appointment.time}} {{business.timezone}}. Please review it carefully, especially any date, time, amount, status, recipient, vehicle, or account detail that may affect what happens next. The information is shown using the local context configured for the relevant workspace whenever that information is available.\n\nThis message is part of the service record for the account or workspace identified above. Keeping these details available helps the right people understand what changed, what is expected next, and which record should be reviewed if questions arise. Review the appointment details carefully and use the available appointment controls if you need a change. If the primary action is no longer available, the record may have changed since this message was generated; open the latest record or contact the responsible team instead of relying on an outdated link.\n\nIf your schedule has changed or any appointment detail is incorrect, contact the service business as soon as possible so the team can help. A member of the service team can clarify the scope, timing, account status, or next step without requiring you to disclose unnecessary sensitive information.\n\nThank you for your attention to this update. Service Writer helps keep the communication record clear, timely, and connected to the underlying service or account activity.", ctaLabel: "View appointment", essentialInformation: "Customer: {{customer.full_name}} | Service: {{appointment.service}} | Date: {{appointment.date}} at {{appointment.time}} {{business.timezone}}", purpose: "appointment_update" },
  "appointment_booking_sequence.booking_received_pending_approval": { key: "appointment_booking_sequence.booking_received_pending_approval", category: "3. Appointment booking sequence", title: "Booking received—pending approval", subject: "We received your booking request", preview: "{{business.name}} received your request. The appointment is not final until the shop approves it.", headline: "We received your booking request", body: "Hello,\n\nThis message concerns your appointment and the service visit it represents. {{business.name}} received your request. The appointment is not final until the shop approves it.\n\nHere is the information currently associated with this update: Requested service: {{appointment.service}} | Requested time: {{appointment.date}} at {{appointment.time}} {{business.timezone}}. Please review it carefully, especially any date, time, amount, status, recipient, vehicle, or account detail that may affect what happens next. The information is shown using the local context configured for the relevant workspace whenever that information is available.\n\nThis message is part of the service record for the account or workspace identified above. Keeping these details available helps the right people understand what changed, what is expected next, and which record should be reviewed if questions arise. Review the appointment details carefully and use the available appointment controls if you need a change. If the primary action is no longer available, the record may have changed since this message was generated; open the latest record or contact the responsible team instead of relying on an outdated link.\n\nIf your schedule has changed or any appointment detail is incorrect, contact the service business as soon as possible so the team can help. A member of the service team can clarify the scope, timing, account status, or next step without requiring you to disclose unnecessary sensitive information.\n\nThank you for your attention to this update. Service Writer helps keep the communication record clear, timely, and connected to the underlying service or account activity.", ctaLabel: "View request", essentialInformation: "Requested service: {{appointment.service}} | Requested time: {{appointment.date}} at {{appointment.time}} {{business.timezone}}", purpose: "appointment_update" },
