  "invoice_and_payment_sequence.account_balance_negative": { key: "invoice_and_payment_sequence.account_balance_negative", category: "7. Invoice and payment sequence", title: "Account balance negative", subject: "Connected account balance is negative", preview: "The connected account balance is below zero and may require action to prevent payment or payout disruption.", headline: "Connected account balance is negative", body: "Hello,\n\nThis message concerns the invoice, balance, or payment activity associated with the service. The connected account balance is below zero and may require action to prevent payment or payout disruption.\n\nHere is the information currently associated with this update: Balance: {{stripe.balance}}. Please review it carefully, especially any date, time, amount, status, recipient, vehicle, or account detail that may affect what happens next. The information is shown using the local context configured for the relevant workspace whenever that information is available.\n\nPlease confirm the business name, amount, and invoice or quote reference before taking action. Payment links should be opened only from this message or the service business’s verified customer portal, and sensitive payment credentials should be entered only on the secure payment page. Review the billing details and use the secure action below if payment or follow-up is required. If the primary action is no longer available, the record may have changed since this message was generated; open the latest record or contact the responsible team instead of relying on an outdated link.\n\nFor billing questions, contact the service business directly. Never send complete card numbers, passwords, or authentication codes by email. A member of the service team can clarify the scope, timing, account status, or next step without requiring you to disclose unnecessary sensitive information.\n\nThank you for your attention to this update. Service Writer helps keep the communication record clear, timely, and connected to the underlying service or account activity.", ctaLabel: "Review account balance", essentialInformation: "Balance: {{stripe.balance}}", purpose: "payment_request" },
