  "staff_onboarding_and_account_management.you_ve_been_invited": { key: "staff_onboarding_and_account_management.you_ve_been_invited", category: "10. Staff onboarding and account management", title: "You’ve been invited", subject: "You’ve been invited to {{workspace.name}}", preview: "You’ve been invited to join a Service Writer workspace. Accept the invitation to access the tools your role requires.", headline: "You’ve been invited to {{workspace.name}}", body: "Hello,\n\nThis message concerns your access, role, or responsibilities within the service business workspace. You’ve been invited to join a Service Writer workspace. Accept the invitation to access the tools your role requires.\n\nHere is the information currently associated with this update: Workspace: {{workspace.name}} | Role: {{staff.role}}. Please review it carefully, especially any date, time, amount, status, recipient, vehicle, or account detail that may affect what happens next. The information is shown using the local context configured for the relevant workspace whenever that information is available.\n\nThis message is part of the service record for the account or workspace identified above. Keeping these details available helps the right people understand what changed, what is expected next, and which record should be reviewed if questions arise. Review the account information and use the secure action below to complete or confirm the requested step. If the primary action is no longer available, the record may have changed since this message was generated; open the latest record or contact the responsible team instead of relying on an outdated link.\n\nIf you did not expect this message, contact your workspace administrator and do not share login credentials or verification codes. A member of the service team can clarify the scope, timing, account status, or next step without requiring you to disclose unnecessary sensitive information.\n\nThank you for your attention to this update. Service Writer helps keep the communication record clear, timely, and connected to the underlying service or account activity.", ctaLabel: "Accept invitation", essentialInformation: "Workspace: {{workspace.name}} | Role: {{staff.role}}", purpose: "transactional" },
